"use strict";
function* tracks() {
  yield "intro";
  yield "verse";
  yield "outro";
}
function* counting() {
  let n = 0;
  for (;;) yield n++;
}
let held;
exports.queue = () => (held = tracks());
exports.sides = () => (held = ["a", "b", "c"].values());
exports.endless = () => (held = counting());
exports.current = () => held;
exports.hold = (it) => (held = it);
exports.isCurrent = (it) => it === held;
exports.upcoming = () => {
  const step = held.next();
  return step.done ? "(end)" : String(step.value);
};
exports.withCurrent = (f) => f(held);
